DO $$
DECLARE v_page jsonb;
BEGIN
CREATE TEMP TABLE temp_import_pages (page_data jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0620000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 62, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "62", "printedPageNumber": 62, "pdfPageNumber": 445, "sequenceIndex": 52, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0620100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith II", "sourceIdentifier": "II", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0620000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 62"}, {"id": "f0620100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "at his place does absolve himself of the obligation. But in the opinion of some of the companions and their successors, salaat with jamaat (after hearing the Azaan) is fardh and its discard is haraam. According to many other theologians, such a person is not even absolved of the obligation in respect of salaat of that hour. Anyhow, he is surely committing the sin of discarding jamaat. In another hadith narrated by Hadhrat Ibn Abbas, it is stated that such a person is guilty of disobedience of Allah and His Apostle (Sallallaho alaihe wasallam). Hadhrat Ibn Abbas (Radhiyallaho anho) also says, \"No good is done by, nor any good is done to, the person who does not join jamaat after hearing the Azaan.\" Hadhrat Abu Hurairah (Radhiyallaho anho) says, \"It is more appropriate to pour molten-lead into the ears of a person who does not go to join jamaat.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 62"}, {"id": "f0620200-0000-4000-8000-000000000001", "structuralNodeId": "b0620100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith II", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 62"}, {"id": "f0620300-0000-4000-8000-000000000001", "structuralNodeId": "b0620100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "قال العلماء كل من سمع النداء فلم يجب فلا صلاة له وقال ﷺ بحسب المؤمن من الشقاء والخيبة أن يسمع المؤذن يثوب بالصلاة فلا يجيبه رواه الطبراني عن معاذ بن أنس كذا في الكنز", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 62"}, {"id": "f0620400-0000-4000-8000-000000000001", "structuralNodeId": "b0620100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Mu''aaz bin Anas (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"A person who does not go for salaat after hearing the Azaan is committing a great wrong and is doing an act of kufr and nifaaq.\"\n\nAccording to this hadith, not to join jamaat after hearing the Azaan is not becoming of a Muslim and is the practice of a kaafir or a munaafiq. What a strong reproof!\n\nIn another hadith, it is said, \"Not to join jamaat after hearing the Azaan is sufficient to render a person most unfortunate and most wretched.\"\n\nHadhrat Sulaimaan bin Abi Hathmah (Radhiyallaho anho) is one of the eminent people of the early days of Islam. He was born during the lifetime of the Prophet (Sallallaho alaihe wasallam), but was too young then to have had the honour of listening to any hadith from him. During the Caliphate of Hadhrat Umar (Radhiyallaho anho) he was made in charge of the market. One day Hadhrat Umar (Radhiyallaho anho) found him missing in Fajr salaat. Hadhrat Umar (Radhiyallaho anho) went to his house and inquired from his mother why Sulaimaan was not present in Fajr. She replied, \"He kept saying nafl salaat throughout the", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 62"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0630000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 63, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "63", "printedPageNumber": 63, "pdfPageNumber": 446, "sequenceIndex": 53, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0630100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith III", "sourceIdentifier": "III", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0630000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part II (b)—Reproach on Discard of Jamaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 63"}, {"id": "f0630100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "night, and sleep overpowered him at the time of Fajr.\" At this, Hadhrat Umar (Radhiyallaho anho) remarked, \"I would prefer my Fajr with jamaat to my offering nafl salaat all night long.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 63"}, {"id": "f0630200-0000-4000-8000-000000000001", "structuralNodeId": "b0630100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith III", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 63"}, {"id": "f0630300-0000-4000-8000-000000000001", "structuralNodeId": "b0630100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن أبي هريرة رضي الله عنه قال قال رسول الله ﷺ لقد هممت أن آمر فتيتي فيجمعوا حزماً من حطب ثم آتي قوماً يصلون في بيوتهم ليست بهم علة فأحرقها عليهم رواه أبو داود وابن ماجه", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 63"}, {"id": "f0630400-0000-4000-8000-000000000001", "structuralNodeId": "b0630100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Hurairah (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"I wish I could ask the boys to collect a huge quantity of firewood for me, and then, I would go around and set fire to the dwellings of those who say their salaat at their own houses without any excuse.\"\n\nThe Prophet (Sallallaho alaihe wasallam), who was most kind and merciful towards his followers and was greatly pained to see them even in a little trouble, gets offended so much that he is ready to set fire to the houses of those who are content with saying salaat at their houses.\n\nHadhrat Abu Darda (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"If there are (even) three persons in a village or in a desert, and they do not say their salaat with jamaat, then Satan gets hold of them. Remember that jamaat for salaat is very necessary for you. Surely a wolf devours a lonely sheep, and Satan is the wolf for men.\"\n\nThis shows that people busy in farming etc. should arrange to say their salaat with jamaat if they are three or more in number. Even if they are two, it is better to have", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 63"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0640000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 64, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "64", "printedPageNumber": 64, "pdfPageNumber": 447, "sequenceIndex": 54, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0640100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith V", "sourceIdentifier": "V", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0640000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 64"}, {"id": "f0640100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "jamaat. The farmers in our country are generally negligent of salaat and consider their occupation a sufficient excuse for their neglect, and even those who are considered pious prefer to perform their salaat individually. If the farmers working in the nearby fields get together at a place and perform prayers in jamaat, they can have quite a big gathering and thereby receive the wonderful blessings of Allah. Notwithstanding the sun, rain, heat and cold, they keep busy for a trifling worldly gain, but lose tremendous amount of Allah''s reward by losing salaat. On the other hand, they can earn a reward fifty times more (as conveyed in another hadith) by offering their salaat with jamaat in the fields.\n\nIt is stated in a hadith, \"When a shepherd calls out the Azaan at the foot of a hill (or in the fields) and starts his salaat, Allah is greatly pleased with him and says proudly to the Angels, ''Behold My slave! He has called out the Azaan and is offering his salaat. All this he does out of fear for Me. I therefore grant him forgiveness and declare his admittance into Paradise.''\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 64"}, {"id": "f0640200-0000-4000-8000-000000000001", "structuralNodeId": "b0640100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith V", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 64"}, {"id": "f0640300-0000-4000-8000-000000000001", "structuralNodeId": "b0640100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن ابن عباس رضي الله عنهما أنه سئل عن رجل يصوم النهار ويقوم الليل ولا يشهد الجمعة ولا الجماعة قال هو في النار رواه الترمذي", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 64"}, {"id": "f0640400-0000-4000-8000-000000000001", "structuralNodeId": "b0640100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Somebody asked Ibn Abbas (Radhiyallaho anho), \"What about a person who keeps fast all day and offers nafl salaat all night, but does not go to the musjid for jamaat and Jumu''ah?\" \"He is doomed to Hell\", replied Hadhrat Ibn Abbas (Radhiyallaho anho).\n\nSuch a person, being a Muslim, may ultimately get freedom from Hell, but who knows after how long. The ignorant among the Soofis and Shaikhs are very particular about Zikr and nafl salaat and consider this an act of eminence in piety, while they are not particular about salaat with jamaat. It must be clearly borne in mind for all times that no person can achieve religious eminence except through complete adherence to the practices of the beloved Prophet (Sallallaho alaihe wasallam).\n\nIt is stated in a hadith that Allah curses three persons: An Imaam who insists on leading the people of a place in salaat, although they do not like him on some reasonable account, a woman who is under the displeasure of her hus-", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 64"}]}'::jsonb);
FOR v_page IN SELECT page_data FROM temp_import_pages LOOP
  PERFORM import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, v_page);
END LOOP;
END;
$$;